<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\{AuthController,DashboardController,ExamController,QuestionController,AttemptController,ResultController,UserController};
Route::get('/',fn()=>auth()->check()?redirect('/dashboard'):view('welcome'))->name('home');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login'])->middleware('throttle:5,1');Route::get('/register',[AuthController::class,'showRegister'])->name('register');Route::post('/register',[AuthController::class,'register'])->middleware('throttle:5,1');});
Route::middleware('auth')->group(function(){Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/dashboard',[DashboardController::class,'index'])->name('dashboard');Route::get('/exams',[ExamController::class,'index'])->name('exams.index');Route::get('/results',[ResultController::class,'index'])->name('results.index');Route::get('/results/{attempt}',[ResultController::class,'show'])->name('results.show');
Route::middleware('role:admin,teacher')->group(function(){Route::get('/exams/create',[ExamController::class,'create'])->name('exams.create');Route::post('/exams',[ExamController::class,'store'])->name('exams.store');Route::get('/exams/{exam}/edit',[ExamController::class,'edit'])->name('exams.edit');Route::put('/exams/{exam}',[ExamController::class,'update'])->name('exams.update');Route::delete('/exams/{exam}',[ExamController::class,'destroy'])->name('exams.destroy');Route::get('/exams/{exam}/questions',[QuestionController::class,'index'])->name('exams.questions.index');Route::post('/exams/{exam}/questions',[QuestionController::class,'store'])->name('exams.questions.store');Route::delete('/exams/{exam}/questions/{question}',[QuestionController::class,'destroy'])->name('exams.questions.destroy');});
Route::middleware('role:student')->group(function(){Route::post('/exams/{exam}/start',[AttemptController::class,'start'])->name('attempts.start');Route::get('/attempts/{attempt}',[AttemptController::class,'show'])->name('attempts.show');Route::post('/attempts/{attempt}/submit',[AttemptController::class,'save'])->name('attempts.submit');});
Route::middleware('role:admin')->group(function(){Route::get('/users',[UserController::class,'index'])->name('users.index');Route::post('/users',[UserController::class,'store'])->name('users.store');Route::put('/users/{user}',[UserController::class,'update'])->name('users.update');Route::delete('/users/{user}',[UserController::class,'destroy'])->name('users.destroy');});});
